def solve(text):
    def program():
        from collections import defaultdict
        N = int(input())
        S = list(input())
        d = defaultdict(int)
        a = 1
        for i in range(N - 1):
            if S[i] == S[i + 1]:
                a += 1
            else:
                a = 1
            d[S[i]] = max(d[S[i]], a)
        if N > 0:
            d[S[-1]] = max(d[S[-1]], a)
        ans = 0
        for i in d.values():
            ans += i
        print(ans)
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

