                a += 1
            else:
                a = 1
            d[S[i]] = max(d[S[i]], a)
        d[S[-1]] = max(d[S[-1]], a)
        ans = 0
        for i in d.values():
            ans += i
        print(ans)
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        A, X, M = map(int, input().split())
        if A == 1:
            print(X % M)
        else:
            print((pow(A, X, M * (A - 1)) - 1) // (A - 1) % M)
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()
